from payload import build_payload


def save(transport, display_name):
    return transport.put("/settings", build_payload(display_name))

import unittest

from client import save


class MemoryTransport:
    def __init__(self):
        self.request = None

    def put(self, path, body):
        self.request = (path, body)
        return {"ok": True}


class ClientTests(unittest.TestCase):
    def test_save(self):
        transport = MemoryTransport()
        self.assertEqual(save(transport, "Ada"), {"ok": True})
        self.assertEqual(transport.request, ("/settings", {"display_name": "Ada"}))

    def test_empty_name(self):
        transport = MemoryTransport()
        save(transport, "")
        self.assertEqual(transport.request[1], {"display_name": ""})

